```yaml
- apt_repository: {repo: deb http://archive.canonical.com/ubuntu hardy partner, state: present}
- apt_repository: {repo: deb http://dl.google.com/linux/chrome/deb/ stable main, filename: google-chrome}
- apt_repository: {repo: deb-src http://archive.canonical.com/ubuntu hardy partner}
- apt_repository: {repo: deb http://archive.canonical.com/ubuntu hardy partner, state: absent}
- apt_repository: {repo: ppa:nginx/stable}
- apt_repository: {repo: 'ppa:nginx/stable', codename: trusty}   # Debian target
```
For keys, download to `/etc/apt/keyrings/*.asc` with get_url and use `signed-by=` in the repo line.
